/**
 * Links from the game to its wiki (Gollum at /wiki, generated by `codex --wiki`).
 *
 * Anything that is game data and has a wiki page gets a "Wiki" right-click
 * option that opens the page in a new tab. Item, spell, vault, shop and
 * container menus add the row themselves; any other element opts in with a
 * `data-wiki="Monsters/goblin"` attribute and gets a small one-row menu here.
 *
 * Page paths match cmd/codex/wiki: Items/<id>, Monsters/<id>, Spells/<id>,
 * NPCs/<id>, Locations/<id> (cities, environments, POIs), Quests/<id>.
 *
 * @module lib/wiki
 */

/** True when the server has a wiki behind /wiki (config `wiki.url`). */
export function wikiEnabled() {
    return window.PQ_WIKI === true;
}

/**
 * The wiki URL for a page.
 * @param {'Items'|'Monsters'|'Spells'|'NPCs'|'Locations'|'Quests'} kind
 * @param {string} id
 */
export function wikiPath(kind, id) {
    return `/wiki/${kind}/${encodeURIComponent(id)}`;
}

/** Open a page ("Monsters/goblin", or kind + id) in a new tab. */
export function openWiki(kindOrPage, id) {
    const url = id === undefined
        ? `/wiki/${kindOrPage.split('/').map(encodeURIComponent).join('/')}`
        : wikiPath(kindOrPage, id);
    window.open(url, '_blank', 'noopener');
}

/** The label every wiki menu row uses. */
export const WIKI_LABEL = '📖 Wiki';

// ─── Menu for [data-wiki] elements ───────────────────────────────────────────

let _menu = null;

function closeMenu() {
    _menu?.remove();
    _menu = null;
}

function showWikiMenu(x, y, page, name) {
    closeMenu();
    const menu = document.createElement('div');
    menu.id = 'wiki-context-menu';
    menu.className = 'fixed bg-gray-800 border-2 border-gray-600 shadow-lg';
    menu.style.cssText += `left: ${x}px; top: ${y}px; min-width: 110px; z-index: 300;`;
    if (name) {
        const header = document.createElement('div');
        header.className = 'px-2 py-1 text-yellow-400 font-bold';
        header.style.fontSize = '8px';
        header.textContent = name;
        menu.appendChild(header);
    }
    const row = document.createElement('div');
    row.className = 'px-2 py-1 hover:bg-gray-700 cursor-pointer text-white';
    row.style.fontSize = '9px';
    row.textContent = WIKI_LABEL;
    row.addEventListener('click', (e) => {
        e.stopPropagation();
        closeMenu();
        openWiki(page);
    });
    menu.appendChild(row);
    document.body.appendChild(menu);
    _menu = menu;
    const rect = menu.getBoundingClientRect();
    if (rect.right > window.innerWidth) menu.style.left = `${window.innerWidth - rect.width - 5}px`;
    if (rect.bottom > window.innerHeight) menu.style.top = `${window.innerHeight - rect.height - 5}px`;
}

document.addEventListener('contextmenu', (e) => {
    if (!wikiEnabled() || e.defaultPrevented) return;
    const el = e.target.closest('[data-wiki]');
    if (!el) return;
    e.preventDefault();
    showWikiMenu(e.clientX, e.clientY, el.dataset.wiki, el.dataset.wikiName);
});
document.addEventListener('click', (e) => {
    if (_menu && !e.target.closest('#wiki-context-menu')) closeMenu();
});
document.addEventListener('keydown', (e) => { if (e.key === 'Escape') closeMenu(); });

window.openWiki = openWiki;
